  1	import { rulesPresets, seaMap, type RulesPresetId } from "@pirate-sea-race/content";
  2	import { intelRules as defaultIntelRules, validateIntelRules, type IntelRules } from "@pirate-sea-race/content/intel";
  3	import { presetRubbingTypes, type RubbingType } from "@pirate-sea-race/content/objectives";
  4	
  5	/** A point in integer sub-units. */
  6	export interface IntelPoint {
  7	  readonly x: number;
  8	  readonly y: number;
  9	}
 10	
 11	/** Static information data for one match; the step reads it and it never changes. */
 12	export interface IntelConfig {
 13	  /** The preset's rubbing types, in the fixed type order. */
 14	  readonly types: readonly RubbingType[];
 15	  readonly widthTiles: number;
 16	  readonly heightTiles: number;
 17	  readonly subUnitsPerTile: number;
 18	  readonly sectorColumns: number;
 19	  readonly sectorRows: number;
 20	  /** Row by row from the north-west. */
 21	  readonly sectorNames: readonly string[];
 22	  /** Island names by island index, as rumors name them. */
 23	  readonly islandNames: readonly string[];
 24	  /** The world tick on which player control starts (§2); every reveal counts from it. */
 25	  readonly controlStartTick: number;
 26	  /** The final island's claim point: its sector goes to everyone, the point itself only to a full-set holder (§5). */
 27	  readonly finalIsland: IntelPoint;
 28	  /** The carrier snapshot beat, which is also the sighting delay and, from the carrier reveal, the broadcast beat. */
 29	  readonly carrierIntervalTicks: number;
 30	  /** Absolute world ticks of §2's minute-20 and minute-28 reveals. */
 31	  readonly sectorRevealTick: number;
 32	  readonly carrierRevealTick: number;
 33	}
 34	
 35	/** The map facts the sectors and rumors need; the content's `SeaMapDefinition` fits. */
 36	export interface IntelMapShape {
 37	  readonly widthTiles: number;
 38	  readonly heightTiles: number;
 39	  readonly subUnitsPerTile: number;
 40	  readonly islands: readonly { readonly name: string }[];
 41	}
 42	
 43	export interface IntelConfigOptions {
 44	  readonly preset: RulesPresetId;
 45	  readonly finalIsland: IntelPoint;
 46	  readonly controlStartTick?: number;
 47	  /** Defaults to the slice sea. */
 48	  readonly map?: IntelMapShape;
 49	  readonly rules?: IntelRules;
 50	}
 51	
 52	export function requireInteger(value: unknown, name: string): void {
 53	  if (typeof value !== "number" || !Number.isSafeInteger(value)) throw new RangeError(`${name} must be a safe integer, got ${String(value)}`);
 54	}
 55	
 56	export function requireId(value: unknown, name: string): void {
 57	  if (typeof value !== "string" || value.length === 0) throw new RangeError(`${name} must be a non-empty string`);
 58	}
 59	
 60	/** Builds a match's information config from the content rules and the map, refusing invalid rules or maps. */
 61	export function createIntelConfig(options: IntelConfigOptions): IntelConfig {
 62	  const rules = validateIntelRules(options.rules ?? defaultIntelRules);
 63	  if (!rules.ok) throw new RangeError(`invalid intel rules: ${rules.issues.join("; ")}`);
 64	  const map = options.map ?? seaMap;
 65	  const start = options.controlStartTick ?? 0;
 66	  requireInteger(start, "controlStartTick");
 67	  if (start < 0) throw new RangeError(`controlStartTick must not be negative, got ${start}`);
 68	  for (const [value, name] of [
 69	    [map.widthTiles, "widthTiles"],
 70	    [map.heightTiles, "heightTiles"],
 71	    [map.subUnitsPerTile, "subUnitsPerTile"],
 72	  ] as const) {
 73	    requireInteger(value, name);
 74	    if (value <= 0) throw new RangeError(`${name} must be positive, got ${value}`);
 75	  }
 76	  if (map.widthTiles < rules.value.sectorColumns || map.heightTiles < rules.value.sectorRows) {
 77	    throw new RangeError(`a ${map.widthTiles} × ${map.heightTiles} map cannot hold ${rules.value.sectorColumns} × ${rules.value.sectorRows} sectors`);
 78	  }
 79	  requireInteger(options.finalIsland.x, "finalIsland.x");
 80	  requireInteger(options.finalIsland.y, "finalIsland.y");
 81	  return {
 82	    types: presetRubbingTypes(rulesPresets[options.preset]),
 83	    widthTiles: map.widthTiles,
 84	    heightTiles: map.heightTiles,
 85	    subUnitsPerTile: map.subUnitsPerTile,
 86	    sectorColumns: rules.value.sectorColumns,
 87	    sectorRows: rules.value.sectorRows,
 88	    sectorNames: [...rules.value.sectorNames],
 89	    islandNames: map.islands.map((island) => island.name),
 90	    controlStartTick: start,
 91	    finalIsland: { x: options.finalIsland.x, y: options.finalIsland.y },
 92	    carrierIntervalTicks: rules.value.carrierIntervalTicks,
 93	    sectorRevealTick: start + rules.value.sectorRevealTicks,
 94	    carrierRevealTick: start + rules.value.carrierRevealTicks,
 95	  };
 96	}
 97	
 98	/**
 99	 * The sector of a tile: the map's columns and rows are cut into `sectorColumns` × `sectorRows` bands by integer
100	 * division, so every tile lies in exactly one sector and the bands differ in width by at most one tile.
101	 */
102	export function sectorOfTile(config: IntelConfig, tileX: number, tileY: number): number {
103	  const x = Math.min(Math.max(tileX, 0), config.widthTiles - 1);
104	  const y = Math.min(Math.max(tileY, 0), config.heightTiles - 1);
105	  const column = Math.floor((x * config.sectorColumns) / config.widthTiles);
106	  const row = Math.floor((y * config.sectorRows) / config.heightTiles);
107	  return row * config.sectorColumns + column;
108	}
109	
110	/** The sector of a sub-unit position: that of its tile. A position off the map counts in the nearest edge sector. */
111	export function sectorOf(config: IntelConfig, position: IntelPoint): number {
112	  return sectorOfTile(config, Math.floor(position.x / config.subUnitsPerTile), Math.floor(position.y / config.subUnitsPerTile));
113	}
114	
115	export function sectorName(config: IntelConfig, sector: number): string {
116	  const name = config.sectorNames[sector];
117	  if (name === undefined) throw new RangeError(`there is no sector ${sector}`);
118	  return name;
119	}
120	
121	// ---------------------------------------------------------------------------------------------------------------------
122	// The world view: what the caller (the match room, from the ledger) tells the step on each tick.
123	
124	/**
125	 * Where a rubbing is, as the ledger's `location` reads once resolved: sealed at a source (its island and position),
126	 * in a recovery cache (its position), owned by a player, or reserved for a player in an unresolved duel.
127	 */
128	export type IntelRubbingPlace =
129	  | { readonly kind: "source"; readonly island: number; readonly x: number; readonly y: number }
130	  | { readonly kind: "cache"; readonly x: number; readonly y: number }
131	  | { readonly kind: "carried"; readonly playerId: string }
132	  | { readonly kind: "duel"; readonly playerId: string };
133	
134	export interface IntelRubbing {
135	  readonly id: string;
136	  readonly type: RubbingType;
137	  readonly place: IntelRubbingPlace;
138	}
139	
140	/** A player still in the match and their ship's position; a carried rubbing is where its carrier is. */
141	export interface IntelPlayerView {
142	  readonly id: string;
143	  readonly x: number;
144	  readonly y: number;
145	}
146	
147	/**
148	 * One world tick as the information rules see it. A player's held types are the types of the rubbings carried by or
149	 * reserved for them, so they cannot disagree with the rubbings; an island is claimed out when no source on it is sealed.
150	 */
151	export interface IntelWorldView {
152	  /** Later than the state's tick; ticks may be skipped. */
153	  readonly tick: number;
154	  readonly players: readonly IntelPlayerView[];
155	  readonly rubbings: readonly IntelRubbing[];
156	}
157	
158	/** A request to buy a targeted rumor (§11). The caller charges the gold only for a `rumor` or `sighting` outcome. */
159	export interface TargetedRumorRequest {
160	  readonly requestId: string;
161	  readonly playerId: string;
162	  readonly type: RubbingType;
163	}
164	
165	export type TargetedRumorResult = "rumor" | "sighting" | "capped" | "none" | "duplicate";
166	
167	export interface TargetedRumorOutcome {
168	  readonly requestId: string;
169	  readonly result: TargetedRumorResult;
170	}
171	
172	// ---------------------------------------------------------------------------------------------------------------------
173	// The state.
174	
175	/** A journal rumor points at an island (a sealed source) or at a sector (a recovery cache), never at a carrier. */
176	export type IntelLeadTarget = { readonly kind: "island"; readonly island: number } | { readonly kind: "sector"; readonly sector: number };
177	
178	export type IntelLeadReason = "start" | "fresh" | "targeted" | "replacement";
179	
180	/** One journal entry. `entry` numbers a player's rumors from 1. */
181	export interface JournalRumor {
182	  readonly entry: number;
183	  readonly type: RubbingType;
184	  readonly target: IntelLeadTarget;
185	  readonly reason: IntelLeadReason;
186	  readonly tick: number;
187	  /** `stale` once the target no longer holds that type; `resolved` once the holder has the type. */
188	  readonly status: "active" | "stale" | "resolved";
189	  readonly closedTick: number | null;
190	}
191	
192	/** A free carrier sighting that met the cap, or found no snapshot to read, waiting for the next snapshot boundary. */
193	export interface PendingSighting {
194	  readonly type: RubbingType;
195	  readonly reason: "start" | "fresh" | "replacement";
196	  readonly tick: number;
197	}
198	
199	export interface IntelPlayerState {
200	  readonly id: string;
201	  /** The held types as of the last processed tick, in type order; losses and completions are diffs of these. */
202	  readonly held: readonly RubbingType[];
203	  readonly journal: readonly JournalRumor[];
204	  /** Whether the player's final-island route is active (they hold a full set) and whether they ever had one. */
205	  readonly routeActive: boolean;
206	  readonly routeEver: boolean;
207	  /** The boundary of the snapshot current when the player last got a carrier sighting, or -1. */
208	  readonly lastSightingBoundary: number;
209	  /** In the order deferred, at most one per type. */
210	  readonly pending: readonly PendingSighting[];
211	}
212	
213	/** One carried copy at a snapshot. The holder is kept only so a player is never shown their own copy. */
214	export interface CarrierSnapshotEntry {
215	  readonly sector: number;
216	  readonly type: RubbingType;
217	  readonly holder: string;
218	}
219	
220	export interface CarrierSnapshot {
221	  /** k for the boundary `controlStartTick + k × carrierIntervalTicks`. */
222	  readonly boundary: number;
223	  /** The tick whose world view it records (the boundary tick unless ticks were skipped). */
224	  readonly tick: number;
225	  readonly entries: readonly CarrierSnapshotEntry[];
226	}
227	
228	/** The information state: plain integer data that `hashState` covers entirely. */
229	export interface IntelState {
230	  /** The last world tick processed. */
231	  readonly tick: number;
232	  readonly rng: number;
233	  /** Whether control start has been processed. */
234	  readonly started: boolean;
235	  /** Players seen in the last view, by id. */
236	  readonly players: readonly IntelPlayerState[];
237	  /** The latest two snapshots, older first. */
238	  readonly snapshots: readonly CarrierSnapshot[];
239	  readonly finalSectorAnnounced: boolean;
240	  readonly sectorRevealed: boolean;
241	  /** The index j of the last carrier broadcast (`carrierRevealTick + j × carrierIntervalTicks`), or -1. */
242	  readonly lastCarrierBroadcast: number;
243	  /** Every targeted request id answered so far, sorted. */
244	  readonly requestIds: readonly string[];
245	}
246	
247	/** A state before any tick. `tick` must come before control start, so control start is always crossed. */
248	export function createIntelState(config: IntelConfig, seed: number, tick = -1): IntelState {
249	  requireInteger(seed, "seed");
250	  requireInteger(tick, "tick");
251	  if (tick >= config.controlStartTick) throw new RangeError(`the intel state must start before control start (tick ${config.controlStartTick})`);
252	  return {
253	    tick,
254	    rng: seed >>> 0,
255	    started: false,
256	    players: [],
257	    snapshots: [],
258	    finalSectorAnnounced: false,
259	    sectorRevealed: false,
260	    lastCarrierBroadcast: -1,
261	    requestIds: [],
262	  };
263	}
264	
265	// ---------------------------------------------------------------------------------------------------------------------
266	// Messages: every one names its recipients. Bodies never carry a player id, a rubbing id or an exact position, except
267	// the final island's point in a `final-route` to a player holding a full set.
268	
269	export type IntelRecipients =
270	  | { readonly kind: "player"; readonly playerId: string }
271	  | { readonly kind: "players"; readonly playerIds: readonly string[] }
272	  | { readonly kind: "everyone" };
273	
274	export interface SectorRef {
275	  readonly sector: number;
276	  readonly name: string;
277	}
278	
279	export type IntelRumorTarget =
280	  | { readonly kind: "island"; readonly island: number; readonly name: string }
281	  | { readonly kind: "sector"; readonly sector: number; readonly name: string };
282	
283	export type IntelMessageBody =
284	  /** A journal lead toward a missing type. */
285	  | { readonly kind: "rumor"; readonly tick: number; readonly entry: number; readonly type: RubbingType; readonly reason: IntelLeadReason; readonly target: IntelRumorTarget }
286	  /** One-shot: the sector where a carrier of the type was at `seenTick` (the previous snapshot). Never tracked. */
287	  | { readonly kind: "carrier-sighting"; readonly tick: number; readonly type: RubbingType; readonly reason: IntelLeadReason; readonly sector: number; readonly name: string; readonly seenTick: number }
288	  /** A free trigger found nothing to point at. */
289	  | { readonly kind: "no-lead"; readonly tick: number; readonly type: RubbingType; readonly reason: IntelLeadReason }
290	  | { readonly kind: "rumor-stale"; readonly tick: number; readonly entry: number; readonly type: RubbingType }
291	  | { readonly kind: "rumor-resolved"; readonly tick: number; readonly entry: number; readonly type: RubbingType }
292	  /** A first full set exists: the final island's broad sector (§5). */
293	  | { readonly kind: "final-sector"; readonly tick: number; readonly sector: number; readonly name: string }
294	  /** The exact route, to a full-set holder only; `restored` after a lost set is whole again. */
295	  | { readonly kind: "final-route"; readonly tick: number; readonly x: number; readonly y: number; readonly restored: boolean }
296	  | { readonly kind: "final-route-inactive"; readonly tick: number }
297	  /** Minute 20: sectors holding sealed sources and recovery caches. */
298	  | { readonly kind: "sector-reveal"; readonly tick: number; readonly sources: readonly SectorRef[]; readonly caches: readonly SectorRef[] }
299	  /** Minute 28 on: the carriers' sectors and types at the latest snapshot. */
300	  | { readonly kind: "carrier-report"; readonly tick: number; readonly seenTick: number; readonly carriers: readonly (SectorRef & { readonly type: RubbingType })[] };
301	
302	export type IntelMessageKind = IntelMessageBody["kind"];
303	
304	export interface IntelMessage {
305	  readonly to: IntelRecipients;
306	  readonly body: IntelMessageBody;
307	}
308	
309	export interface IntelStepResult {
310	  readonly state: IntelState;
311	  readonly messages: readonly IntelMessage[];
312	  /** One per request, in the order given. */
313	  readonly outcomes: readonly TargetedRumorOutcome[];
314	}

