 49	}
 50	
 51	/** Refuses a malformed view: a tick not after `after`, duplicate ids, unknown types, islands or carriers, a doubled type. */
 52	function readView(config: IntelConfig, view: IntelWorldView, after: number): WorldIndex {
 53	  requireInteger(view.tick, "tick");
 54	  if (view.tick <= after) throw new RangeError(`expected a tick after ${after}, got ${view.tick}`);
 55	  const players = new Map<string, IntelPlayerView>();
 56	  for (const player of view.players) {
 57	    requireId(player.id, "player id");
 58	    if (players.has(player.id)) throw new RangeError(`player ${player.id} appears twice`);
 59	    requireInteger(player.x, `${player.id}.x`);
 60	    requireInteger(player.y, `${player.id}.y`);
 61	    players.set(player.id, player);
 62	  }
 63	  const ids = new Set<string>();
 64	  const held = new Map<string, RubbingType[]>([...players.keys()].map((id) => [id, []]));
 65	  const sources: { type: RubbingType; island: number; sector: number }[] = [];
 66	  const caches: { type: RubbingType; sector: number }[] = [];
 67	  const carriers: CarrierSnapshotEntry[] = [];
 68	  for (const rubbing of view.rubbings) {
 69	    requireId(rubbing.id, "rubbing id");
 70	    if (ids.has(rubbing.id)) throw new RangeError(`rubbing ${rubbing.id} appears twice`);
 71	    ids.add(rubbing.id);
 72	    if (!config.types.includes(rubbing.type)) throw new RangeError(`rubbing ${rubbing.id} has a type outside the preset: ${String(rubbing.type)}`);
 73	    const place = rubbing.place;
 74	    switch (place.kind) {
 75	      case "source":
 76	        requireInteger(place.island, `${rubbing.id} island`);
 77	        if (place.island < 0 || place.island >= config.islandNames.length) throw new RangeError(`rubbing ${rubbing.id} names an unknown island ${place.island}`);
 78	        requireInteger(place.x, `${rubbing.id}.x`);
 79	        requireInteger(place.y, `${rubbing.id}.y`);
 80	        sources.push({ type: rubbing.type, island: place.island, sector: sectorOf(config, place) });
 81	        break;
 82	      case "cache":
 83	        requireInteger(place.x, `${rubbing.id}.x`);
 84	        requireInteger(place.y, `${rubbing.id}.y`);
 85	        caches.push({ type: rubbing.type, sector: sectorOf(config, place) });
 86	        break;
 87	      case "carried":
 88	      case "duel": {
 89	        const holder = players.get(place.playerId);
 90	        if (holder === undefined) throw new RangeError(`rubbing ${rubbing.id} is with ${String(place.playerId)}, who is not in the view`);
 91	        const types = held.get(holder.id)!;
 92	        if (types.includes(rubbing.type)) throw new RangeError(`player ${holder.id} holds two ${rubbing.type} rubbings`);
 93	        types.push(rubbing.type);
 94	        carriers.push({ sector: sectorOf(config, holder), type: rubbing.type, holder: holder.id });
 95	        break;
 96	      }
 97	      default:
 98	        throw new RangeError(`rubbing ${rubbing.id} has an unknown place`);
 99	    }
100	  }
101	  for (const types of held.values()) types.sort(byTypeOrder);
102	  carriers.sort((a, b) => a.sector - b.sector || byTypeOrder(a.type, b.type) || compareIds(a.holder, b.holder));
103	  return { tick: view.tick, players, held, sources, caches, carriers };
104	}
