106	// ---------------------------------------------------------------------------------------------------------------------
107	// Planning a lead: sealed sources first, then caches, then a carrier sighting when every other copy is carried.
108	
109	type LeadPlan =
110	  | { readonly kind: "journal"; readonly options: readonly { readonly type: RubbingType; readonly target: IntelLeadTarget }[] }
111	  | {
112	      readonly kind: "carrier";
113	      /** The wanted types whose every copy is carried by someone else. */
114	      readonly types: readonly RubbingType[];
115	      /** Before the carrier reveal, one sighting per player per snapshot. */
116	      readonly capped: boolean;
117	      /** Distinct (type, sector) pairs from the previous snapshot, the player's own entries left out. */
118	      readonly options: readonly { readonly type: RubbingType; readonly sector: number }[];
119	      readonly seenTick: number;
120	    }
121	  | { readonly kind: "none" };
122	
123	interface LeadHolder {
124	  readonly id: string;
125	  readonly journal: readonly JournalRumor[];
126	  readonly lastSightingBoundary: number;
127	}
128	
129	function sameTarget(a: IntelLeadTarget, b: IntelLeadTarget): boolean {
130	  return a.kind === "island" ? b.kind === "island" && a.island === b.island : b.kind === "sector" && a.sector === b.sector;
131	}
132	
133	function uniqueSorted(values: readonly number[]): number[] {
134	  return [...new Set(values)].sort((a, b) => a - b);
135	}
136	
137	function planLead(
138	  config: IntelConfig,
139	  world: WorldIndex,
140	  snapshots: readonly CarrierSnapshot[],
141	  player: LeadHolder,
142	  types: readonly RubbingType[],
143	): LeadPlan {
144	  const held = world.held.get(player.id) ?? [];
145	  const wanted = config.types.filter((type) => types.includes(type) && !held.includes(type));
146	  const active = player.journal.filter((rumor) => rumor.status === "active");
147	  const fresh = (type: RubbingType, target: IntelLeadTarget) => !active.some((rumor) => rumor.type === type && sameTarget(rumor.target, target));
148	
149	  const islands = wanted.flatMap((type) =>
150	    uniqueSorted(world.sources.filter((source) => source.type === type).map((source) => source.island))
151	      .map((island) => ({ type, target: { kind: "island", island } as const }))
152	      .filter((option) => fresh(option.type, option.target)),
153	  );
154	  if (islands.length > 0) return { kind: "journal", options: islands };
155	  const sectors = wanted.flatMap((type) =>
156	    uniqueSorted(world.caches.filter((cache) => cache.type === type).map((cache) => cache.sector))
157	      .map((sector) => ({ type, target: { kind: "sector", sector } as const }))
158	      .filter((option) => fresh(option.type, option.target)),
159	  );
160	  if (sectors.length > 0) return { kind: "journal", options: sectors };
161	
162	  const carried = wanted.filter(
163	    (type) =>
164	      !world.sources.some((source) => source.type === type) &&
165	      !world.caches.some((cache) => cache.type === type) &&
166	      world.carriers.some((carrier) => carrier.type === type && carrier.holder !== player.id),
167	  );
168	  if (carried.length === 0) return { kind: "none" };
169	  const newest = snapshots.at(-1);
170	  const older = snapshots.length === 2 ? snapshots[0]! : undefined;
171	  const capped = world.tick < config.carrierRevealTick && newest !== undefined && player.lastSightingBoundary === newest.boundary;
172	  const options: { type: RubbingType; sector: number }[] = [];
173	  for (const entry of older?.entries ?? []) {
174	    if (entry.holder === player.id || !carried.includes(entry.type)) continue;
175	    if (!options.some((option) => option.type === entry.type && option.sector === entry.sector)) options.push({ type: entry.type, sector: entry.sector });
176	  }
177	  options.sort((a, b) => byTypeOrder(a.type, b.type) || a.sector - b.sector);
178	  return { kind: "carrier", types: carried, capped, options, seenTick: older?.tick ?? -1 };
179	}
