181	/**
182	 * What buying a targeted rumor for `type` would yield for `playerId` now, from the state after its last step and the
183	 * world view of that tick or a later one, without drawing from the generator. A step on a later tick can differ only
184	 * if it first crosses a snapshot boundary or spends the player's sighting on a free trigger.
185	 */
186	export function targetedRumorAvailability(
187	  config: IntelConfig,
188	  state: IntelState,
189	  view: IntelWorldView,
190	  playerId: string,
191	  type: RubbingType,
192	): Exclude<TargetedRumorResult, "duplicate"> {
193	  const world = readView(config, view, state.tick - 1);
194	  if (!state.started || !world.players.has(playerId) || !config.types.includes(type)) return "none";
195	  const player = state.players.find((candidate) => candidate.id === playerId) ?? { id: playerId, journal: [], lastSightingBoundary: -1 };
196	  return targetedResult(planLead(config, world, state.snapshots, player, [type]));
197	}
198	
199	function targetedResult(plan: LeadPlan): Exclude<TargetedRumorResult, "duplicate"> {
200	  if (plan.kind === "journal") return "rumor";
201	  if (plan.kind === "none") return "none";
202	  if (plan.capped) return "capped";
203	  return plan.options.length > 0 ? "sighting" : "none";
204	}
