206	// ---------------------------------------------------------------------------------------------------------------------
207	// The step.
208	
209	interface WorkingPlayer {
210	  id: string;
211	  held: readonly RubbingType[];
212	  journal: JournalRumor[];
213	  routeActive: boolean;
214	  routeEver: boolean;
215	  lastSightingBoundary: number;
216	  pending: PendingSighting[];
217	}
218	
219	function working(player: IntelPlayerState): WorkingPlayer {
220	  return { ...player, journal: [...player.journal], pending: [...player.pending] };
221	}
222	
223	function frozen(player: WorkingPlayer): IntelPlayerState {
224	  return {
225	    id: player.id,
226	    held: [...player.held],
227	    journal: player.journal,
228	    routeActive: player.routeActive,
229	    routeEver: player.routeEver,
230	    lastSightingBoundary: player.lastSightingBoundary,
231	    pending: player.pending,
232	  };
233	}
234	
235	function sectorRef(config: IntelConfig, sector: number): SectorRef {
236	  return { sector, name: sectorName(config, sector) };
237	}
238	
239	/** The latest boundary `origin + k × interval` at or before `tick`, or -1 before `origin`. */
240	function boundaryIndex(tick: number, origin: number, interval: number): number {
241	  return tick < origin ? -1 : Math.floor((tick - origin) / interval);
242	}
243	
244	/**
245	 * One world tick of the information rules, in a fixed order:
246	 *
247	 * 1. Crossing a carrier boundary (every interval from control start) takes a snapshot of the carried copies; the
248	 *    latest two are kept.
249	 * 2. Per player, by id: a starting rumor (at control start, or on first appearance after it); otherwise the diff of
250	 *    held types resolves rumors for types gained, delivers deferred sightings at a boundary, and gives a free fresh
251	 *    rumor per type lost; then rumors whose target was emptied go stale and get a replacement; last, a completed or
252	 *    broken full set announces the final sector and sends or suspends the route.
253	 * 3. Targeted requests, by request id: each gets one outcome; a repeated id gets `duplicate` and changes nothing.
254	 * 4. The minute-20 sector reveal and the minute-28 carrier broadcasts, when their boundary was crossed.
255	 *
256	 * Boundaries fire when crossed since the last processed tick, so a skipped tick never loses one. Before control start
257	 * only the held types are tracked, and no message is sent. The input state is never mutated.
258	 */
259	export function stepIntel(
260	  config: IntelConfig,
261	  state: IntelState,
262	  view: IntelWorldView,
263	  requests: readonly TargetedRumorRequest[] = [],
264	): IntelStepResult {
265	  const world = readView(config, view, state.tick);
266	  for (const request of requests) {
267	    requireId(request.requestId, "request id");
268	    requireId(request.playerId, "request player id");
269	    if (typeof request.type !== "string") throw new RangeError(`request ${request.requestId} has no type`);
270	  }
271	  const tick = world.tick;
272	  let rng = state.rng;
273	  const draw = (bound: number): number => {
274	    const drawn = nextInt(rng, bound);
275	    rng = drawn.state;
276	    return drawn.value;
277	  };
278	  const messages: IntelMessage[] = [];
279	  const toPlayer = (playerId: string, body: IntelMessageBody) => messages.push({ to: { kind: "player", playerId }, body });
280	  const toEveryone = (body: IntelMessageBody) => messages.push({ to: { kind: "everyone" }, body });
281	
282	  const previous = new Map(state.players.map((player) => [player.id, player]));
283	  const players: WorkingPlayer[] = [...world.players.keys()].sort(compareIds).map((id) => {
284	    const known = previous.get(id);
285	    return known
286	      ? working(known)
287	      : { id, held: [], journal: [], routeActive: false, routeEver: false, lastSightingBoundary: -1, pending: [] };
288	  });
289	
290	  // Requests: duplicates are answered without touching anything; the rest are recorded once.
291	  const seen = new Set(state.requestIds);
292	  const outcomes = new Map<number, TargetedRumorResult>();
293	  const accepted: { index: number; request: TargetedRumorRequest }[] = [];
294	  requests.forEach((request, index) => {
295	    if (seen.has(request.requestId)) {
296	      outcomes.set(index, "duplicate");
297	      return;
298	    }
299	    seen.add(request.requestId);
300	    accepted.push({ index, request });
301	  });
302	  const requestIds = seen.size === state.requestIds.length ? state.requestIds : [...seen].sort(compareIds);
303	  const answer = (): TargetedRumorOutcome[] => requests.map((request, index) => ({ requestId: request.requestId, result: outcomes.get(index)! }));
304	
305	  if (tick < config.controlStartTick) {
306	    for (const { index } of accepted) outcomes.set(index, "none");
307	    for (const player of players) player.held = world.held.get(player.id)!;
308	    return { state: { ...state, tick, players: players.map(frozen), requestIds }, messages, outcomes: answer() };
309	  }
310	
311	  // 1. Carrier snapshots.
312	  let snapshots = state.snapshots;
313	  const boundary = boundaryIndex(tick, config.controlStartTick, config.carrierIntervalTicks);
314	  const crossedBoundary = boundary > (snapshots.at(-1)?.boundary ?? -1);
315	  if (crossedBoundary) snapshots = [...snapshots, { boundary, tick, entries: world.carriers }].slice(-2);
316	
317	  const deliverRumor = (player: WorkingPlayer, plan: Extract<LeadPlan, { kind: "journal" }>, reason: IntelLeadReason): void => {
318	    const { type, target } = plan.options[draw(plan.options.length)]!;
319	    const entry = player.journal.length + 1;
320	    player.journal.push({ entry, type, target, reason, tick, status: "active", closedTick: null });
321	    toPlayer(player.id, {
322	      kind: "rumor",
323	      tick,
324	      entry,
325	      type,
326	      reason,
327	      target:
328	        target.kind === "island"
329	          ? { kind: "island", island: target.island, name: config.islandNames[target.island]! }
330	          : { kind: "sector", sector: target.sector, name: sectorName(config, target.sector) },
331	    });
332	  };
333	  const deliverSighting = (player: WorkingPlayer, plan: Extract<LeadPlan, { kind: "carrier" }>, reason: IntelLeadReason): void => {
334	    const { type, sector } = plan.options[draw(plan.options.length)]!;
335	    player.lastSightingBoundary = snapshots.at(-1)!.boundary;
336	    toPlayer(player.id, { kind: "carrier-sighting", tick, type, reason, sector, name: sectorName(config, sector), seenTick: plan.seenTick });
337	  };
338	  /** A free lead (start, loss or journal replacement): a capped or data-less sighting waits for the next boundary. */
339	  const freeLead = (player: WorkingPlayer, types: readonly RubbingType[], reason: PendingSighting["reason"]): void => {
340	    const plan = planLead(config, world, snapshots, player, types);
341	    if (plan.kind === "journal") return deliverRumor(player, plan, reason);
342	    if (plan.kind === "carrier") {
343	      if (!plan.capped && plan.options.length > 0) return deliverSighting(player, plan, reason);
344	      for (const type of plan.types) if (!player.pending.some((pending) => pending.type === type)) player.pending.push({ type, reason, tick });
345	      return;
346	    }
347	    const lacking = config.types.filter((type) => types.includes(type) && !(world.held.get(player.id) ?? []).includes(type));
348	    if (lacking.length > 0) toPlayer(player.id, { kind: "no-lead", tick, type: lacking[0]!, reason });
349	  };
350	
351	  // 2. Players.
352	  const startCrossed = !state.started;
353	  let finalAnnounced = state.finalSectorAnnounced;
354	  for (const player of players) {
355	    const held = world.held.get(player.id)!;
356	    if (startCrossed || !previous.has(player.id)) {
357	      player.held = held;
358	      freeLead(player, config.types, "start");
359	    } else {
360	      const gained = held.filter((type) => !player.held.includes(type));
361	      const lost = player.held.filter((type) => !held.includes(type));
362	      player.held = held;
363	      // Types obtained retire their rumors quietly and cancel their deferred sightings.
364	      player.journal = player.journal.map((rumor) => {
365	        if (rumor.status !== "active" || !gained.includes(rumor.type)) return rumor;
366	        toPlayer(player.id, { kind: "rumor-resolved", tick, entry: rumor.entry, type: rumor.type });
367	        return { ...rumor, status: "resolved", closedTick: tick };
368	      });
369	      player.pending = player.pending.filter((pending) => !held.includes(pending.type));
370	      if (crossedBoundary && player.pending.length > 0) {
371	        const waiting = player.pending;
372	        player.pending = [];
373	        for (const pending of waiting) {
374	          const plan = planLead(config, world, snapshots, player, [pending.type]);
375	          if (plan.kind === "journal") deliverRumor(player, plan, pending.reason);
376	          else if (plan.kind === "carrier" && !plan.capped && plan.options.length > 0) deliverSighting(player, plan, pending.reason);
377	          else if (plan.kind === "carrier") player.pending.push(pending);
378	          else toPlayer(player.id, { kind: "no-lead", tick, type: pending.type, reason: pending.reason });
379	        }
380	      }
381	      // §11: a free fresh rumor for each type lost. Entering a duel is no loss: reserved copies still count as held.
382	      for (const type of lost) freeLead(player, [type], "fresh");
383	    }
384	
385	    // Journal rumors whose island or cache sector no longer holds the type go stale, then get a replacement.
386	    const emptied: RubbingType[] = [];
387	    player.journal = player.journal.map((rumor) => {
388	      if (rumor.status !== "active") return rumor;
389	      const { target } = rumor;
390	      const holds =
391	        target.kind === "island"
392	          ? world.sources.some((source) => source.type === rumor.type && source.island === target.island)
393	          : world.caches.some((cache) => cache.type === rumor.type && cache.sector === target.sector);
394	      if (holds) return rumor;
395	      toPlayer(player.id, { kind: "rumor-stale", tick, entry: rumor.entry, type: rumor.type });
396	      emptied.push(rumor.type);
397	      return { ...rumor, status: "stale", closedTick: tick };
398	    });
399	    for (const type of emptied) freeLead(player, [type], "replacement");
400	
401	    // §5: the first full set announces the final sector to everyone; each holder gets the route while the set is whole.
402	    const complete = config.types.every((type) => held.includes(type));
403	    if (complete && !player.routeActive) {
404	      if (!finalAnnounced) {
405	        finalAnnounced = true;
406	        const sector = sectorOf(config, config.finalIsland);
407	        toEveryone({ kind: "final-sector", tick, sector, name: sectorName(config, sector) });
408	      }
409	      toPlayer(player.id, { kind: "final-route", tick, x: config.finalIsland.x, y: config.finalIsland.y, restored: player.routeEver });
410	      player.routeActive = true;
411	      player.routeEver = true;
412	    } else if (!complete && player.routeActive) {
413	      toPlayer(player.id, { kind: "final-route-inactive", tick });
414	      player.routeActive = false;
415	    }
416	  }
417	
418	  // 3. Targeted rumors (§11), by request id so the order they were listed in never matters.
419	  const byId = new Map(players.map((player) => [player.id, player]));
420	  for (const { index, request } of [...accepted].sort((a, b) => compareIds(a.request.requestId, b.request.requestId) || a.index - b.index)) {
421	    const player = byId.get(request.playerId);
422	    if (player === undefined || !config.types.includes(request.type)) {
423	      outcomes.set(index, "none");
424	      continue;
425	    }
426	    const plan = planLead(config, world, snapshots, player, [request.type]);
427	    const result = targetedResult(plan);
428	    if (result === "rumor") deliverRumor(player, plan as Extract<LeadPlan, { kind: "journal" }>, "targeted");
429	    if (result === "sighting") deliverSighting(player, plan as Extract<LeadPlan, { kind: "carrier" }>, "targeted");
430	    outcomes.set(index, result);
431	  }
432	
433	  // 4. Timed reveals (§2).
434	  let sectorRevealed = state.sectorRevealed;
435	  if (!sectorRevealed && tick >= config.sectorRevealTick) {
436	    sectorRevealed = true;
437	    toEveryone({
438	      kind: "sector-reveal",
439	      tick,
440	      sources: uniqueSorted(world.sources.map((source) => source.sector)).map((sector) => sectorRef(config, sector)),
441	      caches: uniqueSorted(world.caches.map((cache) => cache.sector)).map((sector) => sectorRef(config, sector)),
442	    });
443	  }
444	  let lastCarrierBroadcast = state.lastCarrierBroadcast;
445	  const broadcast = boundaryIndex(tick, config.carrierRevealTick, config.carrierIntervalTicks);
446	  if (broadcast > lastCarrierBroadcast) {
447	    lastCarrierBroadcast = broadcast;
448	    const newest = snapshots.at(-1)!;
449	    const carriers: (SectorRef & { type: RubbingType })[] = [];
450	    for (const entry of newest.entries) {
451	      if (!carriers.some((carrier) => carrier.sector === entry.sector && carrier.type === entry.type)) {
452	        carriers.push({ ...sectorRef(config, entry.sector), type: entry.type });
453	      }
454	    }
455	    toEveryone({ kind: "carrier-report", tick, seenTick: newest.tick, carriers });
456	  }
457	
458	  return {
459	    state: {
460	      tick,
461	      rng,
462	      started: true,
463	      players: players.map(frozen),
464	      snapshots,
465	      finalSectorAnnounced: finalAnnounced,
466	      sectorRevealed,
467	      lastCarrierBroadcast,
468	      requestIds,
469	    },
470	    messages,
471	    outcomes: answer(),
472	  };
473	}
