content.content:
  1	import { rulesPresets, type RulesPresetId } from "@pirate-sea-race/content";
  2	import { presetRubbings } from "@pirate-sea-race/content/objectives";
  3	import { describe, expect, it } from "vitest";
  4	import { nextInt } from "../random.js";
  5	import {
  6	  createIntelConfig,
  7	  createIntelState,
  8	  hashState,
  9	  intelRules,
 10	  replayIntel,
 11	  sectorOf,
 12	  stepIntel,
 13	  type IntelConfig,
 14	  type IntelMapShape,
 15	  type IntelMessage,
 16	  type IntelMessageKind,
 17	  type IntelReplayTick,
 18	  type IntelRubbing,
 19	  type IntelState,
