 25	
 26	type Draw = (bound: number) => number;
 27	
 28	function generator(seed: number): Draw {
 29	  let rng = seed >>> 0;
 30	  return (bound) => {
 31	    const drawn = nextInt(rng, bound);
 32	    rng = drawn.state;
 33	    return drawn.value;
 34	  };
 35	}
 36	
 37	/** Recursively frozen, so a step that mutated its input would throw. */
 38	function deepFreeze<T>(value: T): T {
 39	  if (typeof value === "object" && value !== null && !Object.isFrozen(value)) {
 40	    Object.freeze(value);
 41	    for (const child of Object.values(value)) deepFreeze(child);
 42	  }
 43	  return value;
 44	}
 45	
 46	const T = 256;
 47	/** A slice-sized sea with four islands, and an alpha-sized one with twelve on a 4 × 3 grid. */
 48	const SLICE_MAP: IntelMapShape = { widthTiles: 224, heightTiles: 208, subUnitsPerTile: T, islands: ["Palm Key", "Ash Isle", "Mist Rock", "Old Ruin"].map((name) => ({ name })) };
 49	const ALPHA_MAP: IntelMapShape = { widthTiles: 300, heightTiles: 240, subUnitsPerTile: T, islands: Array.from({ length: 12 }, (_, index) => ({ name: `Isle ${index + 1}` })) };
 50	
 51	function islandPoint(map: IntelMapShape, island: number): { x: number; y: number } {
 52	  const columns = map.islands.length === 4 ? 2 : 4;
 53	  const rows = map.islands.length / columns;
 54	  const column = island % columns;
 55	  const row = Math.floor(island / columns);
 56	  return {
 57	    x: Math.floor(((2 * column + 1) * map.widthTiles * T) / (2 * columns)),
 58	    y: Math.floor(((2 * row + 1) * map.heightTiles * T) / (2 * rows)),
 59	  };
 60	}
 61	
 62	interface Scenario {
 63	  readonly name: string;
 64	  readonly seed: number;
 65	  readonly preset: RulesPresetId;
 66	  /** Compressed reveal times, or the real ones. */
 67	  readonly realTimes: boolean;
 68	  readonly endTick: number;
 69	  /** Per mille of steps that jump ahead by up to 40 ticks. */
 70	  readonly skipPerMille: number;
 71	}
 72	
 73	const START = 60;
 74	const QUICK_RULES = { ...intelRules, carrierIntervalTicks: 100, sightingDelayTicks: 100, sectorRevealTicks: 1_200, carrierRevealTicks: 2_400 };
 75	
 76	const SCENARIOS: readonly Scenario[] = [
 77	  // The real constants past minute 28 and five more carrier intervals: 36,660 ticks after control start.
 78	  { name: "real times, slice", seed: 20260924, preset: "slice", realTimes: true, endTick: START + 36_660, skipPerMille: 0 },
 79	  { name: "quick, slice, seed 1", seed: 1, preset: "slice", realTimes: false, endTick: 3_400, skipPerMille: 0 },
 80	  { name: "quick, slice, seed 2", seed: 2, preset: "slice", realTimes: false, endTick: 3_400, skipPerMille: 0 },
 81	  { name: "quick, alpha, seed 3", seed: 3, preset: "alpha", realTimes: false, endTick: 3_400, skipPerMille: 0 },
 82	  { name: "quick, slice, skipping, seed 4", seed: 4, preset: "slice", realTimes: false, endTick: 3_400, skipPerMille: 300 },
 83	  { name: "quick, alpha, skipping, seed 5", seed: 5, preset: "alpha", realTimes: false, endTick: 3_400, skipPerMille: 300 },
 84	  { name: "real times, alpha, skipping, seed 6", seed: 6, preset: "alpha", realTimes: true, endTick: START + 36_000, skipPerMille: 500 },
 85	];
