309	/**
310	 * Checks every message of a run against the design's rules (§3, §5, §11, §16), with the views that produced them. It
311	 * returns nothing and throws on the first violation, with the tick and message.
312	 */
313	class Checker {
314	  private readonly rumors = new Map<string, { type: RubbingType; closed: boolean; target: unknown }>();
315	  private readonly sightings = new Map<string, number>();
316	  private readonly carriersAt = new Map<number, Facts["carriers"]>();
317	  private readonly ids = new Set<string>();
318	  private previousTick = -Infinity;
319	
320	  constructor(
321	    private readonly config: IntelConfig,
322	    private readonly skipping: boolean,
323	  ) {}
324	
325	  check(view: IntelWorldView, messages: readonly IntelMessage[], state: IntelState): void {
326	    const config = this.config;
327	    const tick = view.tick;
328	    if (tick - this.previousTick > 1 && this.previousTick >= config.controlStartTick) EXERCISED.add("skipped-ticks");
329	    this.previousTick = tick;
330	    const facts = factsOf(config, view);
331	    this.carriersAt.set(tick, facts.carriers);
332	    for (const player of view.players) this.ids.add(player.id);
333	    for (const rubbing of view.rubbings) this.ids.add(rubbing.id);
334	    if (state.players.some((player) => player.pending.length > 0)) EXERCISED.add("sighting:deferred");
335	    const fail = (message: IntelMessage, why: string): never => {
336	      throw new Error(`tick ${tick}: ${why}: ${JSON.stringify(message)}`);
337	    };
338	    if (tick < config.controlStartTick && messages.length > 0) fail(messages[0]!, "a message before control start");
339	    for (const message of messages) {
340	      const body = message.body;
341	      EXERCISED.add(`message:${body.kind}`);
342	      if (body.tick !== tick) fail(message, "wrong tick");
343	      // Keys: exactly the allowed ones, nested ones from the small sector/target vocabulary.
344	      expect(Object.keys(body).sort()).toEqual([...BODY_KEYS[body.kind]]);
345	      for (const nested of ["target", "sources", "caches", "carriers"] as const) {
346	        const value = (body as Record<string, unknown>)[nested];
347	        if (value === undefined) continue;
348	        for (const item of Array.isArray(value) ? value : [value]) {
349	          for (const key of Object.keys(item as object)) if (!NESTED_KEYS.has(key)) fail(message, `nested key ${key}`);
350	        }
351	      }
352	      // No id anywhere in a body.
353	      for (const text of allStrings(body)) if (this.ids.has(text)) fail(message, `the id ${text} leaks`);
354	      // Addressing: broadcasts to everyone, everything else to one player present now.
355	      if (BROADCASTS.has(body.kind)) {
356	        if (message.to.kind !== "everyone") fail(message, "a broadcast addressed to someone");
357	        continue;
358	      }
359	      if (message.to.kind !== "player" || !facts.players.has(message.to.playerId)) fail(message, "not addressed to one present player");
360	      const recipient = (message.to as { playerId: string }).playerId;
361	      const held = facts.held.get(recipient)!;
362	      const complete = config.types.every((type) => held.includes(type));
363	      const key = (entry: number) => `${recipient}#${entry}`;
364	      switch (body.kind) {
365	        case "final-route":
366	          // The only exact position ever sent, and only to a full-set holder.
367	          if (!complete || body.x !== config.finalIsland.x || body.y !== config.finalIsland.y) fail(message, "a route to a player without a full set");
368	          if (body.restored) EXERCISED.add("route:restored");
369	          break;
370	        case "final-route-inactive":
371	          if (complete) fail(message, "a route suspended for a full set");
372	          break;
373	        case "rumor": {
374	          EXERCISED.add(`rumor:${body.reason}`);
375	          EXERCISED.add(`rumor:${body.target.kind}`);
376	          if (held.includes(body.type)) fail(message, "a rumor for a held type");
377	          const target = body.target;
378	          const there =
379	            target.kind === "island"
380	              ? facts.sourceIslands.some((source) => source.type === body.type && source.island === target.island)
381	              : facts.cacheSectors.some((cache) => cache.type === body.type && cache.sector === target.sector);
382	          if (!there) fail(message, "a rumor pointing at nothing");
383	          if (this.rumors.has(key(body.entry))) fail(message, "a journal entry reused");
384	          this.rumors.set(key(body.entry), { type: body.type, closed: false, target });
385	          break;
386	        }
387	        case "rumor-stale":
388	        case "rumor-resolved": {
389	          // Only journal rumors close; a carrier sighting has no entry, so it can never go stale.
390	          const rumor = this.rumors.get(key(body.entry));
391	          if (rumor === undefined || rumor.closed || rumor.type !== body.type) fail(message, "closing no open journal rumor");
392	          rumor!.closed = true;
393	          if (body.kind === "rumor-resolved" && !held.includes(body.type)) fail(message, "resolved without the type");
394	          if (body.kind === "rumor-stale") {
395	            if (held.includes(body.type)) fail(message, "stale although the holder has the type");
396	            const target = rumor!.target as { kind: "island"; island: number } | { kind: "sector"; sector: number };
397	            const there =
398	              target.kind === "island"
399	                ? facts.sourceIslands.some((source) => source.type === body.type && source.island === target.island)
400	                : facts.cacheSectors.some((cache) => cache.type === body.type && cache.sector === target.sector);
401	            if (there) fail(message, "stale while the target still holds the type");
402	          }
403	          break;
404	        }
405	        case "carrier-sighting": {
406	          EXERCISED.add(`sighting:${body.reason}`);
407	          if (held.includes(body.type)) fail(message, "a sighting for a held type");
408	          if (body.seenTick >= tick) fail(message, "a sighting of the present");
409	          const age = tick - body.seenTick;
410	          const interval = config.carrierIntervalTicks;
411	          if (!this.skipping && (age < interval || age >= 2 * interval)) fail(message, `a sighting ${age} ticks old`);
412	          const then = this.carriersAt.get(body.seenTick);
413	          if (then === undefined) fail(message, "a sighting of a tick never seen");
414	          if (!then!.some((carrier) => carrier.type === body.type && carrier.sector === body.sector && carrier.holder !== recipient)) {
415	            fail(message, "a sighting of no other carrier");
416	          }
417	          if (tick < config.carrierRevealTick) {
418	            const snapshot = `${recipient}@${Math.floor((tick - config.controlStartTick) / interval)}`;
419	            const count = (this.sightings.get(snapshot) ?? 0) + 1;
420	            if (count > 1) fail(message, "a second sighting in one snapshot");
421	            this.sightings.set(snapshot, count);
422	          }
423	          break;
424	        }
425	        case "no-lead":
426	          if (held.includes(body.type)) fail(message, "a no-lead for a held type");
427	          break;
428	      }
429	    }
430	  }
431	}
432	
433	function setup(scenario: Scenario) {
434	  const map = scenario.preset === "slice" ? SLICE_MAP : ALPHA_MAP;
435	  const config = createIntelConfig({
436	    preset: scenario.preset,
437	    finalIsland: { x: (map.widthTiles * T) >> 1, y: ((map.heightTiles * T) >> 1) + 77 },
438	    controlStartTick: START,
439	    map,
440	    ...(scenario.realTimes ? {} : { rules: QUICK_RULES }),
441	  });
442	  return { config, script: randomScript(scenario, config, map) };
443	}
444	
445	describe("intel property runs (§3, §5, §11, §16)", () => {
446	  for (const scenario of SCENARIOS) {
447	    it(`keep every message within the rules: ${scenario.name}`, { timeout: 120_000 }, () => {
448	      const { config, script } = setup(scenario);
449	      if (scenario.realTimes && scenario.skipPerMille === 0) {
450	        expect(config.carrierIntervalTicks).toBe(600);
451	        expect(script.at(-1)!.view.tick - config.controlStartTick).toBeGreaterThanOrEqual(36_000);
452	        expect(script.at(-1)!.view.tick).toBeGreaterThan(config.carrierRevealTick + 4 * config.carrierIntervalTicks);
453	      }
454	      const checker = new Checker(config, scenario.skipPerMille > 0);
455	      let state = createIntelState(config, scenario.seed);
456	      const kinds = new Set<string>();
457	      const messages: IntelMessage[] = [];
458	      for (const { view, requests } of script) {
459	        // Frozen (views are frozen too), so a step that wrote into its input would throw.
460	        const stepped = stepIntel(config, deepFreeze(state), view, requests ?? []);
461	        messages.push(...stepped.messages);
462	        expect(stepped.outcomes.map((outcome) => outcome.requestId)).toEqual((requests ?? []).map((request) => request.requestId));
463	        for (const outcome of stepped.outcomes) EXERCISED.add(`outcome:${outcome.result}`);
464	        checker.check(view, stepped.messages, stepped.state);
465	        for (const message of stepped.messages) kinds.add(message.body.kind);
466	        state = stepped.state;
467	      }
468	      // The run reached the reveals it spans.
469	      expect(kinds.has("sector-reveal") && kinds.has("carrier-report")).toBe(true);
470	      // Replaying the same script from the same seed reaches the same state.
471	      const replayed = replayIntel(config, createIntelState(config, scenario.seed), script);
472	      expect(replayed.hash).toBe(hashState(state));
473	      expect(replayed.messages).toEqual(messages);
474	    });
475	  }
476	
477	  it("exercise every message kind, outcome and lead path (EXERCISED)", () => {
478	    expect(MUST_EXERCISE.filter((path) => !EXERCISED.has(path))).toEqual([]);
479	  });
480	});

